export type ParsedAppealInstruction<
  TProgram extends string = typeof ACCORD_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    appellant: TAccountMetas[0];
    subaccord: TAccountMetas[1];
    pauseState: TAccountMetas[2];
    dispute: TAccountMetas[3];
    /**
     * The round just resolved (`dispute.current_round`) — read-only; supplies
     * `reveal_end` for the appeal-window check and `result` (the prior ruling).
     */
    round: TAccountMetas[4];
    /** Per-appeal bond custody (ADR-0004). Keyed by the round being appealed. */
    appealBond: TAccountMetas[5];
    feeToken: TAccountMetas[6];
    appellantTokenAccount: TAccountMetas[7];
    feeVault: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
    associatedTokenProgram: TAccountMetas[10];
    systemProgram: TAccountMetas[11];
  };
  data: AppealInstructionData;
};

export function parseAppealInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedAppealInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      appellant: getNextAccount(),
      subaccord: getNextAccount(),
      pauseState: getNextAccount(),
      dispute: getNextAccount(),
      round: getNextAccount(),
      appealBond: getNextAccount(),
      feeToken: getNextAccount(),
      appellantTokenAccount: getNextAccount(),
      feeVault: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getAppealInstructionDataDecoder().decode(instruction.data),
  };
}
